    zafiro600: { slug: 'automatikuhren-mit-saphirglas-unter-600-euro', h1: 'Automatikuhren mit Saphirglas unter 600 €', title: 'Automatikuhren mit Saphirglas unter 600 €', description: 'Die günstigsten Automatikuhren mit Saphirglas im Katalog, mit Kaliber und Maßen.', criterio: 'Uhren mit Saphirglas und einer mittleren Preisspanne unter 600 €.' },
    zafiro: { slug: 'automatikuhren-mit-saphirglas', h1: 'Automatikuhren mit Saphirglas', title: 'Automatikuhren mit Saphirglas: alle Modelle', description: 'Alle Automatikuhren des Katalogs mit Saphirglas, nach Preis sortiert.', criterio: 'Uhren mit Saphirglas, dem kratzfestesten Glas.' },
