    grandes: { slug: 'grosse-automatikuhren', h1: 'Automatikuhren ab 42 mm', title: 'Große Automatikuhren: 42 bis 45 mm', description: 'Automatikuhren ab 42 mm, mit Horn-zu-Horn-Maß, damit Sie sehen, ob sie an Ihr Handgelenk passen.', criterio: 'Uhren ab 42 mm Durchmesser, von der kleinsten zur größten.' },
